-- 指向当前发布版本 --------------------------------------------------------
UPDATE question_bank SET current_version_id = 1 WHERE id = 1;

-- 序列对齐（显式 id 插入后必须做） ----------------------------------------
SELECT setval(pg_get_serial_sequence('question', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM question), 1));
SELECT setval(pg_get_serial_sequence('bank_version', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM bank_version), 1));
SELECT setval(pg_get_serial_sequence('question_bank', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM question_bank), 1));

