  ($s$isaac-newton$s$, $s$艾萨克·牛顿$s$, NULL, $s$1643–1727$s$, $s$英国$s$, $s$物理 / 数学$s$, $s$INTJ$s$, $s$inferred$s$, 0.6, $j${"EI":0.8,"SN":0.6,"TF":-0.85,"JP":-0.6}$j$::jsonb, $j$["孤独的专注","公理化思维","对批评不宽容"]$j$::jsonb, $s$在无人问津的房间里推演几十年，用几条公理统摄整个物理世界——先建模，再验证。$s$, $s$如果说我看得更远，那是因为我站在巨人的肩上。$s$, $s$致胡克信，1675$s$, NULL, $j${"url":"","license":"PD-old","credit":"Wikimedia Commons"}$j$::jsonb, $j$[]$j$::jsonb, $s$published$s$, now(), now()),
  ($s$sun-wu$s$, $s$孙武$s$, $s$孙子$s$, $s$约前545–约前470$s$, $s$中国·春秋$s$, $s$军事理论$s$, $s$INTJ$s$, $s$inferred$s$, 0.45, $j${"EI":0.6,"SN":0.7,"TF":-0.6,"JP":-0.8}$j$::jsonb, $j$["先算后战","结构化解构","反直觉"]$j$::jsonb, $s$《孙子兵法》几乎不谈勇武，只谈计算与形势：先算赢，再开战。$s$, $s$兵者，国之大事，死生之地，存亡之道，不可不察也。$s$, $s$《孙子兵法·计篇》$s$, NULL, $j${"url":"","license":"PD-old","credit":"Wikimedia Commons"}$j$::jsonb, $j$[]$j$::jsonb, $s$published$s$, now(), now()),
  ($s$marie-curie$s$, $s$玛丽·居里$s$, $s$居里夫人$s$, $s$1867–1934$s$, $s$波兰 / 法国$s$, $s$物理 / 化学$s$, $s$INTJ$s$, $s$inferred$s$, 0.5, $j${"EI":0.6,"SN":0.7,"TF":-0.7,"JP":-0.75}$j$::jsonb, $j$["长期主义","极简生活","体系化推进"]$j$::jsonb, $s$在漏雨的棚屋里提炼四年，把一件事做到极致——驱动她的不是热情，是体系。$s$, NULL, NULL, NULL, $j${"url":"","license":"check-required","credit":"Wikimedia Commons"}$j$::jsonb, $j$[]$j$::jsonb, $s$published$s$, now(), now()),
  ($s$albert-einstein$s$, $s$阿尔伯特·爱因斯坦$s$, NULL, $s$1879–1955$s$, $s$德国 / 美国$s$, $s$物理$s$, $s$INTP$s$, $s$inferred$s$, 0.7, $j${"EI":0.6,"SN":0.9,"TF":-0.7,"JP":0.8}$j$::jsonb, $j$["思想实验","从前提入手","抗拒权威"]$j$::jsonb, $s$他推翻的不是某个结论，而是整个前提——从根部重建逻辑，是 Ti 最典型的手势。$s$, $s$想象力比知识更重要。$s$, $s$1929 年访谈$s$, NULL, $j${"url":"","license":"check-required","credit":"Wikimedia Commons"}$j$::jsonb, $j$[]$j$::jsonb, $s$published$s$, now(), now()),
  ($s$zhuangzi$s$, $s$庄子$s$, $s$庄周$s$, $s$约前369–前286$s$, $s$中国·战国$s$, $s$哲学$s$, $s$INTP$s$, $s$disputed$s$, 0.4, $j${"EI":0.7,"SN":0.95,"TF":-0.3,"JP":0.9}$j$::jsonb, $j$["解构常识","寓言思维","拒绝结论"]$j$::jsonb, $s$用一个接一个的寓言拆掉你习以为常的框架，从不给结论，只给视角。$s$, $s$天地与我并生，而万物与我为一。$s$, $s$《齐物论》$s$, $s$也有人归为 ENTP（好辩）或 INFP（价值驱动），本表取 Ti-Ne 的解读。$s$, $j${"url":"","license":"PD-old","credit":"Wikimedia Commons"}$j$::jsonb, $j$[]$j$::jsonb, $s$published$s$, now(), now()),
  ($s$immanuel-kant$s$, $s$伊曼努尔·康德$s$, NULL, $s$1724–1804$s$, $s$德国$s$, $s$哲学$s$, $s$INTP$s$, $s$disputed$s$, 0.45, $j${"EI":0.85,"SN":0.7,"TF":-0.8,"JP":0.2}$j$::jsonb, $j$["概念手术","极端自律","终身未离开小城"]$j$::jsonb, $s$每天同一时间散步，只为把脑子里那套庞大的体系搭完——极端的秩序服务于极端的抽象。$s$, $s$有两样东西，愈是经常而持久地思考，愈使心灵充满景仰与敬畏：头上的星空和心中的道德律。$s$, $s$《实践理性批判》$s$, $s$也有研究者据其刻板作息判为 ISTJ，本表取思维方式的解读。$s$, $j${"url":"","license":"PD-old","credit":"Wikimedia Commons"}$j$::jsonb, $j$[]$j$::jsonb, $s$published$s$, now(), now()),
